CREATE TABLE operational_entities (
 customer_id TEXT NOT NULL REFERENCES customers(id), domain TEXT NOT NULL, collection TEXT NOT NULL,
 entity_id TEXT NOT NULL, payload TEXT NOT NULL, source_version INTEGER NOT NULL,
 status TEXT, service_date TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(customer_id,domain,collection,entity_id)
);
CREATE INDEX entities_filter ON operational_entities(customer_id,domain,collection,status,service_date,entity_id);
CREATE TRIGGER commercial_entities_insert AFTER INSERT ON commercial_workspaces BEGIN INSERT INTO operational_entities(customer_id,domain,collection,entity_id,payload,source_version,status,service_date) SELECT NEW.customer_id,'commercial',c.key,COALESCE(json_extract(j.value,'$.id'),json_extract(j.value,'$.barcode'),json_extract(j.value,'$.vehicleId'),json_extract(j.value,'$.accountId')),j.value,NEW.version,COALESCE(json_extract(j.value,'$.status'),json_extract(j.value,'$.stage')),COALESCE(json_extract(j.value,'$.date'),json_extract(j.value,'$.due')) FROM json_each(NEW.payload) c JOIN json_each(c.value) j WHERE c.key IN ('accounts','locations','contacts','activities','tasks','agreements','estimates','plans','jobs','invoices','payments','outbox') AND COALESCE(json_extract(j.value,'$.id'),json_extract(j.value,'$.barcode'),json_extract(j.value,'$.vehicleId'),json_extract(j.value,'$.accountId')) IS NOT NULL ON CONFLICT(customer_id,domain,collection,entity_id) DO UPDATE SET payload=excluded.payload,source_version=excluded.source_version,status=excluded.status,service_date=excluded.service_date,updated_at=CURRENT_TIMESTAMP WHERE operational_entities.payload<>excluded.payload; END;
CREATE TRIGGER commercial_entities_update AFTER UPDATE OF payload ON commercial_workspaces BEGIN
 DELETE FROM operational_entities WHERE customer_id=NEW.customer_id AND domain='commercial' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload)c JOIN json_each(c.value)j WHERE c.key=operational_entities.collection AND c.key IN ('accounts','locations','contacts','activities','tasks','agreements','estimates','plans','jobs','invoices','payments','outbox') AND COALESCE(json_extract(j.value,'$.id'),json_extract(j.value,'$.barcode'),json_extract(j.value,'$.vehicleId'),json_extract(j.value,'$.accountId'))=operational_entities.entity_id);
